<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Physical copies | Digital Library</title><link rel="stylesheet" href="/assets/app.css"></head><body>
<header class="site-header"><a class="brand" href="/dashboard">Digital Library</a><nav><a href="/manage/books">Books</a></nav></header><main class="container"><p class="eyebrow">Collection management</p><h1>Physical copies</h1>
<?php if ($error): ?><p class="form-error" role="alert"><?= e($error) ?></p><?php endif; ?><?php if ($success): ?><p class="form-success" role="status"><?= e($success) ?></p><?php endif; ?>
<form method="post" class="book-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label for="book_id">Book</label><select id="book_id" name="book_id" required><option value="">Select book</option><?php foreach ($books as $book): ?><option value="<?= e((string) $book['id']) ?>"><?= e($book['title']) ?></option><?php endforeach; ?></select><label for="accession_number">Accession number</label><input id="accession_number" name="accession_number" required maxlength="64"><label for="condition_label">Condition</label><input id="condition_label" name="condition_label" value="good" required maxlength="80"><label for="location">Location</label><input id="location" name="location" required maxlength="120"><button type="submit">Add copy</button></form>
<section class="catalog" aria-labelledby="copy-list"><div class="section-heading"><h2 id="copy-list">Copies</h2><span class="muted"><?= e((string) count($copies)) ?></span></div><?php if ($copies === []): ?><div class="empty-state"><h3>No physical copies yet</h3></div><?php else: ?><div class="book-grid"><?php foreach ($copies as $copy): ?><article class="book-card"><p class="eyebrow"><?= e($copy['status']) ?></p><h3><?= e($copy['title']) ?></h3><p><?= e($copy['accession_number']) ?> · <?= e($copy['location']) ?></p><?php if (!in_array($copy['status'], ['borrowed', 'reserved'], true)): ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?= e((string) $copy['id']) ?>"><label for="status-<?= e((string) $copy['id']) ?>">Status</label><select id="status-<?= e((string) $copy['id']) ?>" name="status"><option value="available">Available</option><option value="maintenance">Maintenance</option><option value="lost">Lost</option><option value="damaged">Damaged</option></select><button type="submit">Update status</button></form><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?></section></main></body></html>